import json, re, sys, collections


def cat(w, text):
    if w.startswith('erp:start'):
        return 'erp start'
    if w.startswith('erp:'):
        return 'erp search' if 'SearchReport' in text else 'erp detail'
    if w.startswith('mail:'):
        return 'mail kinds'
    if w == 'mail':
        return 'mail addr/TAN'
    if w.startswith('customer-portal'):
        return 'spec (both)'
    if w == 'tender-portal:qa':
        return 'tender qa'
    if w == 'tender-portal:tender':
        return 'tender docs'
    if w == 'tender-portal':
        return 'bid form/sign'
    return w


for path in sys.argv[1:]:
    L = [json.loads(l) for l in open(path)]
    txt = ''.join(x['text'] for x in L if x['stream'] == 'stdout')
    i = txt.find('===== run summary')
    j = txt.find('===== end of run summary')
    agg = collections.defaultdict(lambda: [0, 0, 0, 0, 0.0, 0])
    for line in txt[i:j].splitlines():
        m = re.match(r'\[\s*([\d.]+)s\] (\S+)\s+(\S+)\s+(.*)', line)
        if not m:
            continue
        w, kind, rest = m.group(2), m.group(3), m.group(4)
        r = re.search(r'requests=(\d+)', rest)
        if not r:
            continue
        a = agg[cat(w, rest)]
        a[0] += int(r.group(1))
        for k, idx in (('input_tokens', 1), ('cached_tokens', 2), ('output_tokens', 3)):
            mm = re.search(k + r'=(\d+)', rest)
            if mm:
                a[idx] += int(mm.group(1))
        s = re.search(r'seconds=([\d.]+)', rest)
        if s:
            a[4] += float(s.group(1))
        a[5] += 1
    print(path)
    tot = [0, 0, 0, 0]
    for k, a in sorted(agg.items(), key=lambda kv: -kv[1][1]):
        cost = ((a[1] - a[2]) * 0.15 + a[2] * 0.016 + a[3] * 0.47) / 1e6
        print(f'  {k:16} runs={a[5]:3} req={a[0]:4} in={a[1]:8} cached={a[2]:7} out={a[3]:6} '
              f'worker_s={a[4]:7.1f} cost=${cost:.4f}')
        for n in range(4):
            tot[n] += a[n]
    print('  sum', tot)

